const b = $json.body || {};
if (!/^[0-9a-fA-F-]{36}$/.test(String(b.project_id || ''))) throw new Error('project_id không hợp lệ');
if (!/^[a-z0-9-]{1,64}$/.test(String(b.shot_slug || ''))) throw new Error('shot_slug không hợp lệ');
if (!['approve', 'regenerate'].includes(b.action)) throw new Error('action phải là approve hoặc regenerate');
return [{ json: { project_id: b.project_id, shot_slug: b.shot_slug, action: b.action } }];

// Dựng prompt từ Asset Bible rồi vẽ keyframe mock (SVG) cho MỘT shot, ghi rõ số phiên bản.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const wrap = (text, n) => {
  const lines = [];
  let cur = '';
  for (const w of String(text || '').split(' ')) {
    if ((cur + ' ' + w).trim().length > n) { lines.push(cur); cur = w; }
    else { cur = (cur + ' ' + w).trim(); }
  }
  if (cur) lines.push(cur);
  return lines;
};
const font = 'Helvetica, Arial, sans-serif';
return $input.all().map(item => {
  const j = item.json;
  const loc = j.location || {};
  const chars = (j.characters || []).map(c => {
    const acc = (c.accessories || []).join(', ');
    return `${c.name} (${c.gender}, ${c.age} tuổi, ${c.appearance}, ${c.outfit}${acc ? ', ' + acc : ''})`;
  }).join('; ');
  const prompt = `Góc máy ${j.camera}. ${j.setting} ${loc.name} (${loc.description}), ${j.time_of_day}, ánh sáng: ${loc.lighting}. Tâm trạng: ${j.mood}. Nhân vật: ${chars || 'không có'}. Hành động: ${j.action}`;
  const lines = wrap(j.action, 46).slice(0, 6);
  const body = lines.map((l, i) => `<text x="80" y="${300 + i * 48}" font-size="34" fill="#ffffff" font-family="${font}">${esc(l)}</text>`).join('');
  // Mỗi phiên bản xoay màu một chút để nhìn thấy ngay là đã sinh lại.
  const shift = ((Number(j.version) || 1) - 1) * 40;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1" gradientTransform="rotate(${shift} .5 .5)"><stop offset="0" stop-color="#ff8a3d"/><stop offset="0.5" stop-color="#ff4f9a"/><stop offset="1" stop-color="#7a4dff"/></linearGradient></defs><rect width="1280" height="720" fill="url(#g)"/><text x="80" y="120" font-size="56" font-weight="700" fill="#ffffff" font-family="${font}">${esc(j.slug)} · ${esc(j.camera)} · v${esc(j.version)}</text><text x="80" y="190" font-size="28" fill="#ffffff" fill-opacity="0.8" font-family="${font}">KEYFRAME MOCK</text>${body}</svg>`;
  const url = 'data:image/svg+xml;base64,' + Buffer.from(svg).toString('base64');
  return { json: { shot_id: j.shot_id, slug: j.slug, version: j.version, prompt, url } };
});
